edits.after:
/// Returns a mutable reference to the value currently stored in the
/// `SetOnce`, or `None` if the `SetOnce` is empty.
///
/// Since this call borrows the `SetOnce` mutably, the mutable borrow
/// statically guarantees that no other references to the value exist.
pub fn get_mut(&mut self) -> Option<&mut T> {
    if self.initialized() {
        // SAFETY: The value is initialized, and `&mut self` guarantees
        // exclusive access for the lifetime of the returned reference.
        Some(unsafe { &mut *self.value.with_mut(|ptr| (*ptr).as_mut_ptr()) })
    } else {
        None
    }
}

/// Sets the value of the `SetOnce` to the given value if the `SetOnce` is
/// empty.

#[test]
fn into_inner_int_empty_setonce() {
    let once = SetOnce::<u32>::new();

    let val = once.into_inner();

    assert!(val.is_none());
}

#[test]
fn get_mut_empty() {
    let mut once = SetOnce::new();

    assert!(once.get_mut().is_none());
    assert!(!once.initialized());
    assert_eq!(once.get(), None);

    assert!(once.set(5).is_ok());
    assert_eq!(once.get_mut(), Some(&mut 5));
    assert_eq!(once.into_inner(), Some(5));
}

#[tokio::test]
async fn get_mut_preserves_mutations() {
    let mut once = SetOnce::new();
    assert!(once.set(String::from("hello")).is_ok());

    once.get_mut().unwrap().push_str(" world");
    once.get_mut().unwrap().push('!');

    assert!(once.initialized());
    assert_eq!(once.get().unwrap(), "hello world!");
    assert_eq!(once.wait().await, "hello world!");
    assert!(once.set(String::from("replacement")).is_err());
    assert_eq!(once.into_inner(), Some(String::from("hello world!")));
}

#[test]
fn get_mut_new_with_drops_once() {
    let counter = DropCounter::new();
    let mut once = SetOnce::new_with(Some((String::from("before"), counter.clone())));

    once.get_mut().unwrap().0.push_str(" after");
    assert!(once.initialized());
    assert_eq!(once.get().unwrap().0, "before after");
    counter.assert_num_drops(0);

    drop(once);
    counter.assert_num_drops(1);
}

#[test]
fn get_mut_into_inner_transfers_ownership() {
    let counter = DropCounter::new();
    let mut once = SetOnce::new();
    assert!(once.set((String::from("before"), counter.clone())).is_ok());

    once.get_mut().unwrap().0.push_str(" after");
    counter.assert_num_drops(0);

    let value = once.into_inner().unwrap();
    assert_eq!(value.0, "before after");
    counter.assert_num_drops(0);
    drop(value);
    counter.assert_num_drops(1);
}

